import {image,esc,arrow,carouselControls} from '../homepage/ui.js';
import {header,footer} from '../homepage/sections.js';
import {propertyCard} from '../homepage/cards.js';
import {objectData as d} from './data.js';
import {mapImage} from './media.js';

function gallery(){return `<section class="object-gallery" aria-label="Фотографии квартиры" tabindex="0"><div class="gallery-stage">${image(d.gallery[0].src,d.gallery[0].alt,'','id="object-photo" width="665" height="416" fetchpriority="high"')}<button class="gallery-arrow previous" data-photo-step="-1" aria-label="Предыдущее фото">${arrow('left')}</button><button class="gallery-arrow next" data-photo-step="1" aria-label="Следующее фото">${arrow()}</button><button class="gallery-expand" data-gallery-open aria-label="Открыть фотографии на весь экран"><img src="object-page/assets/full_screen.svg" alt="" width="36" height="36"></button></div><div class="gallery-thumbnails">${d.gallery.map((p,i)=>`<button data-photo="${i}" aria-label="Фото ${i+1}" aria-pressed="${i===0}">${image(p.src,p.alt,'','width="155" height="95"')}</button>`).join('')}</div><output id="gallery-status" class="visually-hidden" aria-live="polite">Фото 1 из ${d.gallery.length}</output></section>`;}
function summary(){return `<section class="object-summary" aria-labelledby="object-title"><div class="summary-content"><h1 id="object-title">${esc(d.title)}</h1><p class="object-address">${esc(d.address)}</p><dl class="object-quick-facts"><div><dt>Площадь:</dt><dd>36 м<sup>2</sup></dd></div><div><dt>Жилая площадь:</dt><dd>16 м<sup>2</sup></dd></div><div><dt>Этаж:</dt><dd>2/10</dd></div><div><dt>Комнаты:</dt><dd>1</dd></div><div><dt>Стены:</dt><dd>Кирпич</dd></div></dl><div class="object-price-row"><div><p class="object-price">${d.price.toLocaleString('ru-RU')} руб</p><p class="object-unit-price">${d.pricePerMeter.toLocaleString('ru-RU')} руб/м<sup>2</sup></p></div><button class="mortgage-teaser" data-calculator><span>от 10 000 руб. / мес.*</span><small>Рассчитать ипотеку</small></button></div></div><div class="object-agent"><div class="agent-avatar">${image(d.agent.image,d.agent.name,'','width="55" height="75"')}<button class="agent-call" data-consult="Связаться с агентом" aria-label="Связаться с агентом ${esc(d.agent.name)}"><img src="object-page/assets/phone-call.svg" alt="" width="22" height="22"></button></div><div class="agent-caption"><p><strong>${esc(d.agent.name)}</strong><small>Специалист по недвижимости</small></p><p><a class="agent-phone" href="tel:${d.agent.phone.replace(/[^+\d]/g,'')}">${esc(d.agent.phone)}</a><a class="agent-email" href="mailto:${esc(d.agent.email)}">${esc(d.agent.email)}</a></p></div></div></section>`;}
function overview(){return `<div class="object-overview"><section class="object-description" aria-labelledby="description-title"><h2 id="description-title">Описание</h2><p>${esc(d.description)}</p></section><aside class="object-safety" aria-labelledby="safety-title"><h2 id="safety-title">Безопасная сделка</h2><ul>${d.safety.map(t=>`<li>${image('object-page/assets/li.svg','','safety-marker','width="8" height="11"')}<span>${esc(t)}</span></li>`).join('')}</ul></aside></div>`;}
function features(){return `<section class="object-features" aria-labelledby="features-title"><h2 id="features-title">Подробные характеристики</h2><div class="features-columns">${d.features.map(group=>`<section><h3>${esc(group.title)}</h3><dl>${group.rows.map(([label,value])=>`<div><dt><span>${esc(label)}</span></dt><dd>${esc(value)}</dd></div>`).join('')}</dl></section>`).join('')}</div></section>`;}
function map(){return `<section class="object-location" aria-labelledby="map-title"><div class="map-heading"><h2 id="map-title">На карте</h2><a href="#similar">Предложения рядом</a></div><button class="object-map" data-map aria-label="Увеличить карту из макета">${mapImage(d.mapImage)}</button></section>`;}
function similar(){return `<section class="object-similar" id="similar" aria-labelledby="similar-title"><p class="eyebrow">Удобно</p><h2 id="similar-title">Похожие объекты</h2><div class="property-grid">${d.similar.map(propertyCard).join('')}</div>${carouselControls('similar','Все объекты',d.similar.length,'property-catalog.html')}</section>`;}
export function objectPage(){return `${header({light:true,contactDetails:d.contacts,linkBase:'homepage.html'})}<main id="object-page"><div class="container"><div class="object-toolbar"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="homepage.html">Главная</a><span aria-hidden="true">/</span><a href="property-catalog.html">Недвижимость</a><span aria-hidden="true">/</span><a href="property-catalog.html">Квартиры</a><span aria-hidden="true">/</span><span aria-current="page">${esc(d.title)}</span></nav><div class="object-meta"><p>Номер в каталоге <span>${esc(d.catalogNumber)}</span></p><p>Добавлено: <time>${esc(d.addedDate)}</time></p></div></div><div class="object-hero">${gallery()}${summary()}</div>${overview()}${features()}${map()}${similar()}</div></main>${footer(d.footer,{contactDetails:d.contacts,linkBase:'homepage.html'})}`;}
